<template>
    <div class="comparison-panel" role="region" :aria-label="`${title} audio comparison`">
        <table class="comparison-table">
            <caption class="comparison-caption">{{ title }} audio comparison</caption>
            <thead>
                <tr>
                    <th scope="col" class="sample-info">Sample Info</th>
                    <th v-for="model in models" :key="model" scope="col" class="model-label">{{ formatModelLabel(model) }}</th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="(row, index) in rows" :key="index">
                    <th scope="row" class="sample-info">
                        <h5 class="sample-title">{{ row.item.title }}</h5>
                        <p v-if="row.item.text" class="sample-lyrics">{{ row.item.text }}</p>
                        <p v-if="row.item.pronunciation" class="sample-pronunciation">{{ row.item.pronunciation }}</p>
                        <div v-for="reference in row.references" :key="reference.name" class="reference-audio">
                            <span class="reference-label">{{ reference.name }}</span>
                            <audio v-if="reference.src" :src="reference.src" controls preload="none"
                                :aria-label="`${title} - ${row.item.title} - ${reference.name}`"
                                @play="handlePlay($event)"></audio>
                            <span v-else class="unavailable">Not available</span>
                        </div>
                    </th>
                    <td v-for="model in row.models" :key="model.name" :data-label="formatModelLabel(model.name)">
                        <div class="reference-audio">
                            <span v-if="model.audio && model.audio.promptSrc" class="reference-label">Generated</span>
                            <audio v-if="model.audio && model.audio.src" :src="model.audio.src" controls preload="none"
                                :aria-label="`${title} - ${row.item.title} - ${model.name}${model.audio.promptSrc ? ' - Generated' : ''}`"
                                @play="handlePlay($event)"></audio>
                            <span v-else class="unavailable">Not available</span>
                        </div>
                        <div v-if="model.audio && model.audio.promptSrc" class="reference-audio">
                            <span class="reference-label">Prompt</span>
                            <audio :src="model.audio.promptSrc" controls preload="none"
                                :aria-label="`${title} - ${row.item.title} - ${model.name} - Prompt`"
                                @play="handlePlay($event)"></audio>
                        </div>
                        <button v-if="model.audio && model.audio.imageSrc" type="button"
                            class="alignment-preview" aria-haspopup="dialog"
                            :aria-label="`${title} - ${row.item.title} - ${model.name} - Enlarge alignment image`"
                            @click="openAlignment($event, row.item, model)">
                            <img :src="model.audio.imageSrc"
                                :alt="`${row.item.title} - ${model.name} alignment`" loading="lazy" decoding="async">
                            <span class="alignment-caption">{{ model.audio.imageCaption || 'Alignment' }} · Click to enlarge</span>
                        </button>
                    </td>
                </tr>
            </tbody>
        </table>
        <dialog ref="alignmentDialog" class="alignment-dialog"
            :aria-label="zoomedAlignment ? zoomedAlignment.label : 'Alignment preview'"
            :style="zoomedAlignment ? { '--alignment-zoom-width': zoomedAlignment.width + 'px' } : null"
            @click="handleAlignmentBackdrop" @close="resetAlignmentZoom">
            <div v-if="zoomedAlignment" class="alignment-zoom-content">
                <div class="alignment-zoom-header">
                    <h3>{{ zoomedAlignment.label }}</h3>
                    <button type="button" class="alignment-close" autofocus
                        aria-label="Close enlarged alignment image" @click="closeAlignment">Close</button>
                </div>
                <img class="alignment-zoom-image" :src="zoomedAlignment.src" :alt="zoomedAlignment.alt">
            </div>
        </dialog>
    </div>
</template>

<script>
const referenceNames = ['GT', 'Prompt'];

export default {
    name: 'ComparisonTable',
    props: {
        title: String,
        items: {
            type: Array,
            default: () => []
        }
    },
    data() {
        return {
            zoomedAlignment: null,
            alignmentTrigger: null
        };
    },
    computed: {
        models() {
            const names = new Set();
            this.items.forEach(item => {
                (item.audio || []).forEach(audio => {
                    if (!referenceNames.includes(audio.name)) names.add(audio.name);
                });
            });
            return Array.from(names);
        },
        rows() {
            return this.items.map(item => {
                const audio = item.audio || [];
                return {
                    item,
                    references: referenceNames.map(name => audio.find(sample => sample.name === name)).filter(Boolean),
                    models: this.models.map(name => ({ name, audio: audio.find(sample => sample.name === name) }))
                };
            });
        }
    },
    beforeDestroy() {
        this.closeAlignment();
        this.pausePlayers();
    },
    methods: {
        openAlignment(event, item, model) {
            const image = event.currentTarget.querySelector('img');
            this.alignmentTrigger = event.currentTarget;
            this.zoomedAlignment = {
                src: model.audio.imageSrc,
                alt: `${item.title} - ${model.name} alignment`,
                label: `${this.title} - ${item.title} - ${model.name}`,
                width: image.getBoundingClientRect().width * 3
            };
            this.$nextTick(() => {
                const dialog = this.$refs.alignmentDialog;
                if (dialog && this.zoomedAlignment && !dialog.open) dialog.showModal();
            });
        },
        closeAlignment() {
            const dialog = this.$refs.alignmentDialog;
            if (dialog && dialog.open) dialog.close();
        },
        handleAlignmentBackdrop(event) {
            const dialog = this.$refs.alignmentDialog;
            if (event.target !== dialog) return;
            const rect = dialog.getBoundingClientRect();
            if (event.clientX < rect.left || event.clientX > rect.right
                || event.clientY < rect.top || event.clientY > rect.bottom) {
                this.closeAlignment();
            }
        },
        resetAlignmentZoom() {
            const trigger = this.alignmentTrigger;
            this.zoomedAlignment = null;
            this.alignmentTrigger = null;
            if (trigger && trigger.isConnected) trigger.focus({ preventScroll: true });
        },
        formatModelLabel(name) {
            return name.replace(/\s+(\([^()]*\))$/, '\n$1');
        },
        handlePlay(event) {
            this.pausePlayers(event.target);
            this.$emit('play', event.target);
        },
        pausePlayers(currentPlayer) {
            this.$el.querySelectorAll('audio').forEach(player => {
                if (player !== currentPlayer) player.pause();
            });
        }
    }
};
</script>

