<template>
    <b-container fluid class="mb-3 page-section">
        <b-row>
            <b-card :title="experiment.title" class="mb-2 experiment-card">
                <b-card-text v-show="!usesComparisonTable">
                    <b-row>
                        <b-col>
                            <audio ref="audioPlayer" preload="auto" controls
                                @play="audioError = ''"></audio>
                            <p v-if="audioError" class="text-danger" role="alert">{{ audioError }}</p>
                        </b-col>
                    </b-row>
                </b-card-text>
                <b-card-text v-show="!usesComparisonTable">
                    <b-row>
                        <b-col>
                            <h5>{{ play_title }}</h5>
                            <p>{{ play_text }}</p>
                            <p v-if="gifLoading" role="status">Loading animation...</p>
                            <img v-if="gifSrc" :key="gifSrc" :src="gifSrc" :alt="gifAlt"
                                class="sample-gif" @error="handleGifError">
                            <p v-if="gifError" class="text-danger" role="alert">{{ gifError }}</p>
                        </b-col>
                    </b-row>
                </b-card-text>
                <b-row>
                    <b-col>
                        <b-tabs v-model="activeDataset" content-class="mt-3">
                            <b-tab v-for="(dataset, index) of experiment.datasets" 
                                :key="index" 
                                :title="dataset.title"
                                :active="dataset.title === `CNN/Daily Mail`? true : false">

                                <ComparisonTable v-if="dataset.layout === 'comparison'"
                                    :items="dataset.samples"
                                    :title="dataset.title"
                                    @play="handleInlinePlay" />
                                <SampleTable v-else
                                    :items="dataset.samples" 
                                    :title="dataset.title" 
                                    @playAudio="handlePlayAudio" />
                            </b-tab>
                        </b-tabs>
                    </b-col>
                </b-row>
            </b-card>
        </b-row>
    </b-container>
</template>

<script>
/* eslint-env browser */
import SampleTable from './SampleTable.vue';
import ComparisonTable from './ComparisonTable.vue';

export default {
    name: "SectionVue",
    components: {
        SampleTable,
        ComparisonTable
    },
    props: {
        experiment: Object
    },
    data() {
        return {
            activeDataset: 0,
            play_title: "",
            play_text: "Please click the button placed on each sample to play",
            gifSrc: "",
            gifAlt: "",
            gifLoading: false,
            gifError: "",
            audioError: "",
            playRequest: 0
        }
    },
    computed: {
        usesComparisonTable() {
            const dataset = this.experiment.datasets[this.activeDataset]
            return dataset && dataset.layout === 'comparison'
        }
    },
    watch: {
        activeDataset() {
            this.$el.querySelectorAll('audio').forEach(player => player.pause())
            this.playRequest += 1
            this.clearGif()
            this.gifLoading = false
        }
    },
    beforeDestroy() {
        this.playRequest += 1
        this.$refs.audioPlayer.pause()
        this.clearGif()
    },
    methods: {
        handleInlinePlay() {
            this.$refs.audioPlayer.pause()
        },
        handlePlayAudio({ sample, title, text }) {
            if (!sample.src && !sample.gifSrc) return

            const request = ++this.playRequest
            const player = this.$refs.audioPlayer
            player.pause()
            player.removeAttribute('src')
            player.load()
            this.clearGif()
            this.gifError = ""
            this.audioError = ""
            this.gifLoading = false
            this.play_title = `${title} (${sample.name})`
            this.play_text = text
            this.gifAlt = sample.gifAlt || `${title} (${sample.name}) animation`

            if (sample.gifSrc) {
                this.loadGif(sample.gifSrc, request)
            }

            if (sample.src) {
                player.src = sample.src
                const playback = player.play()
                if (playback && playback.catch) {
                    playback.catch(() => {
                        if (request === this.playRequest) {
                            this.audioError = "Audio could not start. Please try the audio controls."
                        }
                    })
                }
            }
        },
        async loadGif(src, request) {
            this.gifLoading = true
            try {
                const response = await fetch(src)
                if (!response.ok) throw new Error('Unable to load GIF')
                const blob = await response.blob()
                if (request !== this.playRequest) return

                // A fresh object URL restarts the GIF even when selecting the same sample.
                this.gifSrc = URL.createObjectURL(blob)
            } catch {
                if (request === this.playRequest) {
                    this.gifError = "Animation could not load. Please try the sample again."
                }
            } finally {
                if (request === this.playRequest) this.gifLoading = false
            }
        },
        handleGifError(event) {
            if (event.target.src !== this.gifSrc) return
            this.clearGif()
            this.gifError = "Animation could not be displayed. Please check the GIF file."
        },
        clearGif() {
            if (this.gifSrc) URL.revokeObjectURL(this.gifSrc)
            this.gifSrc = ""
        }
    },
}
</script>

<style scoped>
.experiment-card {
    width: 100%;
    min-width: 0;
}

.sample-gif {
    display: block;
    max-width: 100%;
    max-height: 480px;
    height: auto;
    margin: 0 auto 1rem;
    object-fit: contain;
}
</style>
